@import 'tailwindcss';
@import 'tw-animate-css';
@import 'shadcn/tailwind.css';

@custom-variant dark (&:is(.dark *));

@theme inline {
  --font-sans: var(--font-geist-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, monospace;
  --color-positive: var(--positive);
  --color-positive-foreground: var(--positive-foreground);
  --color-negative: var(--negative);
  --color-negative-foreground: var(--negative-foreground);
  --color-gold: var(--gold);
  --color-gold-foreground: var(--gold-foreground);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --color-foreground: var(--foreground);
  --color-background: var(--background);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);

  --animate-flip-in: flip-in 0.45s ease-out both;
  --animate-pop: pop 0.25s ease-out both;
  --animate-shake: shake 0.4s ease-in-out;

  @keyframes flip-in {
    0% { transform: rotateX(90deg); opacity: 0; }
    100% { transform: rotateX(0deg); opacity: 1; }
  }
  @keyframes pop {
    0% { transform: scale(0.92); opacity: 0; }
    100% { transform: scale(1); opacity: 1; }
  }
  @keyframes shake {
    0%, 100% { transform: translateX(0); }
    20%, 60% { transform: translateX(-6px); }
    40%, 80% { transform: translateX(6px); }
  }
}

:root {
  color-scheme: light;
  --background: oklch(0.985 0.002 250);
  --foreground: oklch(0.18 0.01 255);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.18 0.01 255);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.18 0.01 255);
  --primary: oklch(0.6 0.15 160);
  --primary-foreground: oklch(0.99 0 0);
  --secondary: oklch(0.95 0.004 250);
  --secondary-foreground: oklch(0.22 0.01 255);
  --muted: oklch(0.95 0.004 250);
  --muted-foreground: oklch(0.48 0.012 255);
  --accent: oklch(0.94 0.006 250);
  --accent-foreground: oklch(0.22 0.01 255);
  --destructive: oklch(0.57 0.17 25);
  --border: oklch(0.9 0.006 250);
  --input: oklch(0.9 0.006 250);
  --ring: oklch(0.6 0.15 160);
  --positive: oklch(0.6 0.15 160);
  --positive-foreground: oklch(0.99 0 0);
  --negative: oklch(0.57 0.17 25);
  --negative-foreground: oklch(0.99 0 0);
  --gold: oklch(0.7 0.14 78);
  --gold-foreground: oklch(0.2 0.03 78);
  --chart-1: oklch(0.6 0.15 160);
  --chart-2: oklch(0.57 0.17 25);
  --chart-3: oklch(0.7 0.14 78);
  --chart-4: oklch(0.55 0.1 250);
  --chart-5: oklch(0.6 0.02 255);
  --radius: 0.75rem;
  --sidebar: oklch(0.98 0 0);
