  --sidebar-ring: oklch(0.6 0.15 160);
}

.dark {
  color-scheme: dark;
  --background: oklch(0.155 0.006 260);
  --foreground: oklch(0.96 0.004 250);
  --card: oklch(0.195 0.007 260);
  --card-foreground: oklch(0.96 0.004 250);
