@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
  .tabular {
    font-variant-numeric: tabular-nums;
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
/* Bellwether: a quiet financial editorial, with a terminal underneath. */
:root { --font-geist-sans: 'Arial'; --font-geist-mono: 'Courier New'; }
.dark { --background: #0c1012; --card: #13191c; --popover: #192126; --muted: #20292d; --muted-foreground: #8c9ba2; --primary: #62e5b1; --primary-foreground: #082b1d; --positive: #62e5b1; --border: #ffffff12; }
body { letter-spacing: -.015em; }
button, a { -webkit-tap-highlight-color: transparent; }
button:not(:disabled), a { cursor: pointer; }
a, button { outline-offset: 5px; }
:focus-visible { outline: 2px solid var(--primary); }
.eyebrow { font-size: 10px; font-weight: 600; letter-spacing: .14em; color: var(--primary); display: flex; align-items: center; gap: 8px; }
.session-bar { display:flex; align-items:center; justify-content:space-between; gap: 12px; padding: 24px 0; font-family: var(--font-mono); font-size:9px; letter-spacing:.08em; color:var(--muted-foreground); border-bottom:1px solid var(--border); }
.session-bar>span:first-child {display:flex;align-items:center;gap:8px;}
.status-dot {display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--primary);box-shadow:0 0 12px #62e5b140;flex-shrink:0;}
.demo-pill {font-size:8px;letter-spacing:.12em;border:1px solid var(--border);padding:5px 7px;border-radius:4px;}
.hero-grid {display:grid;grid-template-columns:1.04fr 1fr;gap:48px;align-items:center;padding:57px 0 43px;}
.hero-copy h1 {font-size:clamp(44px,4.6vw,63px);font-weight:650;letter-spacing:-.055em;line-height:1.08;margin:20px 0 19px;}
.hero-copy h1 em {font-style:normal;color:var(--primary);}
.hero-copy>p {font-size:14px;color:var(--muted-foreground);line-height:1.85;}
.hero-copy>p.hero-data-note {font-size:10px;margin-top:7px;opacity:.75;}
.short-line {width:19px;height:1px;background:var(--primary);}
.hero-actions {display:flex;align-items:center;gap:23px;margin-top:26px;flex-wrap:wrap;}
.primary-action {display:flex;align-items:center;justify-content:center;gap:20px;padding:14px 19px;border-radius:7px;background:var(--primary);color:var(--primary-foreground);font-size:12px;font-weight:700;transition:transform .2s,filter .2s;}
.primary-action:hover {filter:brightness(1.06);transform:translateY(-2px);}
.quiet-action {display:flex;align-items:center;gap:8px;font-size:11px;font-weight:500;color:var(--muted-foreground);}
.hero-footnote {display:flex;align-items:center;gap:8px;margin-top:20px;font-size:9px;color:var(--muted-foreground);}
.hero-footnote svg {color:var(--primary);}
.hero-footnote>span {width:3px;height:3px;background:var(--muted-foreground);border-radius:50%;margin:0 2px;}
.hero-terminal {border:1px solid #62e5b125;border-radius:12px;background:linear-gradient(140deg,#62e5b108,transparent 50%),var(--card);overflow:hidden;box-shadow:0 20px 80px -35px #0008;transform:rotate(-1deg);}
.terminal-top {display:flex;justify-content:space-between;font-family:var(--font-mono);font-size:8px;letter-spacing:.08em;padding:15px 20px;border-bottom:1px solid var(--border);color:var(--muted-foreground);}
.terminal-top>span:first-child {display:flex;align-items:center;gap:6px;}
.terminal-top i {width:4px;height:4px;background:var(--primary);border-radius:50%;}
.terminal-company {display:flex;align-items:center;gap:10px;padding:24px 20px 0;}
.mystery-icon {width:39px;height:39px;border-radius:9px;border:1px solid #62e5b130;background:#62e5b10c;display:grid;place-items:center;color:var(--primary);font-family:var(--font-mono);font-size:23px;}
.terminal-company .text-xs {font-size:7px;letter-spacing:.1em;}
.terminal-company h2 {font-size:14px;margin-top:3px;font-weight:500;}
.terminal-ticker {margin-left:auto;font-family:var(--font-mono);font-size:11px;letter-spacing:.2em;color:var(--muted-foreground);}
.terminal-chart {position:relative;margin:24px 20px 20px 20px;padding-right:30px;}
.terminal-chart>svg {width:100%;height:157px;}
.chart-guide {position:absolute;right:0;top:12px;height:123px;display:flex;flex-direction:column;justify-content:space-between;font-size:7px;font-family:var(--font-mono);color:var(--muted-foreground);}
.chart-months {display:flex;justify-content:space-between;color:var(--muted-foreground);font-family:var(--font-mono);font-size:7px;letter-spacing:.05em;margin-top:5px;}
.terminal-clues {display:grid;grid-template-columns:1fr 1fr 1fr;gap:7px;padding:0 20px 20px;}
.terminal-clues>div {background:#62e5b108;border:1px solid var(--border);padding:10px;border-radius:5px;}
.terminal-clues span {display:block;font-size:7px;letter-spacing:.1em;color:var(--muted-foreground);}
.terminal-clues b {font-family:var(--font-mono);font-size:10px;font-weight:400;display:flex;align-items:center;justify-content:space-between;color:var(--primary);margin-top:7px;}
.terminal-bottom {display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--border);padding:14px 20px;font-size:10px;}
.terminal-bottom>span {display:flex;align-items:center;gap:7px;}
.terminal-bottom small {font-size:9px;color:var(--muted-foreground);}
.terminal-bottom>svg {color:var(--primary);}
.personal-strip {display:flex;align-items:center;border:1px solid var(--border);border-radius:9px;background:var(--card);padding:20px;gap:20px;}
.strip-heading {display:flex;align-items:center;gap:12px;flex:1;}
.strip-heading>svg {color:var(--gold);}
.strip-heading strong {display:block;font-size:12px;font-weight:500;}
.strip-heading div>span {display:block;color:var(--muted-foreground);font-size:10px;margin-top:4px;}
.strip-stat {padding:0 25px;border-left:1px solid var(--border);}
.strip-stat>span {display:flex;align-items:center;gap:7px;font-family:var(--font-mono);font-size:21px;font-weight:500;}
.strip-stat small {display:block;font-size:7px;letter-spacing:.12em;color:var(--muted-foreground);margin-top:6px;}
.strip-link {color:var(--muted-foreground);}
.games-section {margin-top:49px;}
.section-heading {display:flex;align-items:center;justify-content:space-between;gap:20px;}
.section-heading h2 {font-size:27px;letter-spacing:-.045em;font-weight:550;margin-top:9px;}
.section-heading p {font-size:11px;color:var(--muted-foreground);margin-top:8px;}
.reset-chip {display:flex;gap:9px;align-items:center;color:var(--muted-foreground);font-size:9px;border:1px solid var(--border);padding:9px 12px;border-radius:6px;}
.reset-chip .font-mono {font-size:11px;color:var(--foreground);margin-left:7px;}
.reset-chip small {font-size:8px;}
.daily-progress {display:flex;align-items:center;gap:20px;margin:24px 0 17px;font-size:10px;color:var(--muted-foreground);}
.daily-progress>div:first-child {display:flex;gap:12px;}
.daily-progress b {font-weight:500;color:var(--primary);}
.daily-progress b span {color:var(--muted-foreground);font-weight:400;}
.progress-track {display:flex;flex:1;gap:5px;}
.progress-track span {flex:1;height:3px;border-radius:4px;background:var(--muted);}
.progress-track .filled {background:var(--primary);}
.game-grid {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px;}
.game-card {--game-color:var(--primary);position:relative;display:flex;flex-direction:column;border:1px solid var(--border);border-radius:10px;padding:20px 20px 0;background:var(--card);overflow:hidden;transition:border-color .2s,transform .2s;}
.game-card:hover {transform:translateY(-4px);border-color:var(--game-color);}
.game-card.flagship {border-color:#62e5b145;background:radial-gradient(ellipse at 100% 0%,#62e5b10c,transparent 70%),var(--card);}
.game-card.blue {--game-color:#88baff;}.game-card.violet {--game-color:#baa0f7;}.game-card.gold {--game-color:#e9c26d;}.game-card.rose {--game-color:#e8a4ae;}
.game-card-top {display:flex;align-items:center;justify-content:space-between;}
.game-icon {padding:9px;border-radius:9px;color:var(--game-color);background:color-mix(in srgb,var(--game-color) 10%,transparent);}
.game-card-top>span {display:flex;align-items:center;gap:4px;color:var(--game-color);font-family:var(--font-mono);font-size:7px;letter-spacing:.08em;}
.game-visual {height:104px;display:flex;align-items:center;justify-content:center;margin:6px 0 10px;color:var(--game-color);}
.mini-grid {display:grid;grid-template-columns:repeat(5,25px);gap:4px;transform:rotate(-6deg);}
.mini-grid span {height:23px;border-radius:3px;display:flex;align-items:center;justify-content:center;font-size:10px;background:var(--muted);color:var(--muted-foreground);}
.mini-grid .hit {background:#43b28266;border:1px solid #62e5b145;color:#90ebbc;}.mini-grid .near {background:#ab8d384d;color:#e9c26d;}
.mini-versus {display:flex;align-items:center;gap:16px;width:90%;font-family:var(--font-mono);}
.mini-versus>span {border:1px solid var(--border);border-radius:8px;text-align:center;flex:1;padding:13px 10px;font-size:9px;background:color-mix(in srgb,var(--game-color) 3%,transparent);}
.mini-versus b {display:block;font-size:21px;font-weight:400;margin-top:9px;color:var(--foreground);}
.mini-versus i {font-style:normal;font-size:9px;color:var(--muted-foreground);}
.mini-chart {width:90%;height:72px;}
.mini-bars {width:80%;display:flex;flex-direction:column;gap:6px;}
.mini-bars>div {display:flex;align-items:center;gap:10px;font-size:7px;font-family:var(--font-mono);}.mini-bars span{width:25px;}.mini-bars i{height:9px;background:color-mix(in srgb,var(--game-color) 50%,transparent);border-radius:2px;}
.mini-trivia {display:flex;flex-direction:column;width:90%;gap:6px;font-size:9px;}.mini-trivia>span:first-child{color:var(--foreground);}.mini-trivia b{display:flex;align-items:center;gap:8px;border:1px solid color-mix(in srgb,var(--game-color) 25%,transparent);background:color-mix(in srgb,var(--game-color) 8%,transparent);padding:8px;border-radius:4px;font-weight:400;}.mini-trivia>span:last-child{padding:8px;border:1px solid var(--border);color:var(--muted-foreground);border-radius:4px;}
.game-tag {font-family:var(--font-mono);font-size:7px;letter-spacing:.14em;color:var(--game-color);margin-bottom:8px;}
.game-card h3 {font-size:20px;font-weight:550;letter-spacing:-.035em;}
.game-card>p {font-size:11px;line-height:1.8;color:var(--muted-foreground);margin-top:8px;max-width:260px;}
.game-meta {font-size:9px;color:var(--muted-foreground);margin:17px 0 18px;flex:1;}
.game-meta span{display:flex;align-items:center;gap:8px;}.game-meta i{width:2px;height:2px;border-radius:50%;background:var(--muted-foreground);}
.game-card-bottom {display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--border);margin:0 -20px;padding:13px 20px;color:var(--game-color);font-size:10px;font-weight:500;}
.bottom-grid {display:grid;grid-template-columns:1.6fr 1fr;gap:16px;margin-top:34px;}
.fact-card,.habit-card{border:1px solid var(--border);border-radius:10px;padding:26px;background:var(--card);}
.fact-card {display:flex;gap:20px;}.fact-symbol{color:var(--gold);padding:10px;height:fit-content;background:#e9c26d0c;border:1px solid #e9c26d15;border-radius:9px;}.fact-card .eyebrow{color:var(--gold);font-size:8px;}
.fact-card h3,.habit-card h3 {font-size:18px;font-weight:500;line-height:1.5;margin-top:10px;letter-spacing:-.035em;}
.fact-card p,.habit-card p{font-size:10px;line-height:1.9;color:var(--muted-foreground);margin-top:9px;}.fact-card a,.habit-card a{display:flex;align-items:center;gap:7px;color:var(--primary);font-size:9px;margin-top:17px;}
.habit-card {background:radial-gradient(ellipse at bottom right,#62e5b10a,transparent),var(--card);}.habit-card .eyebrow{font-size:8px;}
.dialog-backdrop{position:fixed;inset:0;z-index:100;background:#000a;backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:20px;}.help-dialog{position:relative;inset:auto;margin:auto;background:var(--card);color:var(--foreground);border:1px solid var(--border);border-radius:18px;padding:32px;max-width:530px;max-height:90vh;overflow:auto;}.dialog-close{position:absolute;right:17px;top:17px;color:var(--muted-foreground);}.help-dialog h2{font-size:27px;line-height:1.25;font-weight:600;letter-spacing:-.04em;margin-top:15px;}.help-dialog ol{list-style:decimal;padding-left:20px;margin:22px 0;font-size:13px;line-height:1.8;color:var(--muted-foreground);}.help-dialog li{padding:7px 0;}.help-dialog b{color:var(--foreground);}.help-dialog p{font-size:12px;line-height:1.8;color:var(--muted-foreground);margin-bottom:24px;}
